'use strict';
const { createCache } = require('./src/cache');
const tick = () => new Promise(r => setImmediate(r));
function deferred() { let resolve, reject; const promise = new Promise((a, b) => { resolve = a; reject = b; }); return { promise, resolve, reject }; }
const check = (name, ok) => console.log(`${ok ? 'PASS' : 'FAIL'} ${name}`);

(async () => {
  // 1. Rejection must not be cached.
  {
    let calls = 0;
    const cache = createCache({ now: () => 0, load() { calls++; if (calls === 1) throw 'boom'; return 'ok'; } });
    const r = await cache.get('k').catch(e => `rej:${e}`);
    const r2 = await cache.get('k').catch(e => `rej:${e}`);
    check('rejection retried', r === 'rej:boom' && r2 === 'ok' && calls === 2);
  }
  // 2. Stale flight resolving after newer flight started must not evict/overwrite it.
  {
    const gates = [deferred(), deferred()]; let calls = 0;
    const cache = createCache({ now: () => 0, load() { return gates[calls++].promise; } });
    const a = cache.get('k'); await tick();
    cache.invalidate('k');
    const b = cache.get('k'); await tick();
    gates[0].resolve('stale'); await a; await tick();
    const b2 = cache.get('k');
    check('newer flight still deduped', calls === 2);
    gates[1].resolve('fresh');
    check('readers get fresh', (await b) === 'fresh' && (await b2) === 'fresh');
    check('stored fresh', (await cache.get('k')) === 'fresh' && calls === 2);
  }
  // 3. set wins over earlier load and its TTL is not restarted.
  {
    let t = 0; const gate = deferred(); let calls = 0;
    const cache = createCache({ now: () => t, ttlMs: 10, load() { calls++; return calls === 1 ? gate.promise : 'new'; } });
    const a = cache.get('k'); await tick();
    cache.set('k', 'set');
    t = 5; gate.resolve('old'); check('old reader gets old', (await a) === 'old'); await tick();
    check('set value wins', (await cache.get('k')) === 'set');
    t = 10;
    check('set TTL not restarted', (await cache.get('k')) === 'new' && calls === 2);
  }
  // 4. Stale rejection must not evict newer flight.
  {
    const gates = [deferred(), deferred()]; let calls = 0;
    const cache = createCache({ now: () => 0, load() { return gates[calls++].promise; } });
    const a = cache.get('k'); await tick();
    cache.clear();
    const b = cache.get('k'); await tick();
    gates[0].reject(new Error('x')); await a.catch(() => {}); await tick();
    cache.get('k');
    check('stale rejection keeps newer flight', calls === 2);
    gates[1].resolve('v'); await b;
  }
  // 5. load calling set synchronously.
  {
    let calls = 0; let cache;
    cache = createCache({ now: () => 0, load(k) { calls++; cache.set(k, 'manual'); return 'loaded'; } });
    const a = await cache.get('k');
    check('sync set inside load wins', a === 'loaded' && (await cache.get('k')) === 'manual' && calls === 1);
  }
})();

