'use strict';

// A detached flight still settles its original callers. The registry tracks
// only flights available for subsequent readers of each key.
function createFlights() {
  const pending = new Map();

  return {
    run(key, work, commit) {
      if (pending.has(key)) return pending.get(key).promise;
      const flight = { promise: null };
      // Only the flight still registered for key may commit or unregister;
      // a detached flight must neither store its value nor evict a newer one.
      const release = () => {
        if (pending.get(key) !== flight) return false;
        pending.delete(key);
        return true;
      };
      flight.promise = Promise.resolve().then(work).then(
        value => {
          if (release()) commit(value);
          return value;
        },
        reason => {
          release();
          throw reason;
        }
      );
      pending.set(key, flight);
      return flight.promise;
    },
    forget(key) {
      pending.delete(key);
    },
    clear() {
      pending.clear();
    }
  };
}

module.exports = { createFlights };
